import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.sql.*;
import java.util.logging.*;
import java.util.regex.*;
import java.io.*;
import java.util.*;

@WebServlet("/api/reports/*")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9]+$");

    // Connection pool configured via JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String pathInfo = req.getPathInfo();
        String format = req.getParameter("format");
        String userId = req.getRemoteUser();

        if (pathInfo == null || pathInfo.equals("/")) {
            resp.sendError(400, "Missing report path");
            return;
        }

        String[] parts = pathInfo.substring(1).split("/");
        if (parts.length < 2) {
            resp.sendError(400, "Invalid path");
            return;
        }

        String reportType = parts[0];
        String reportId = parts[1];

        // Validate reportId is numeric
        if (!SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        try {
            String result = fetchReport(reportType, reportId, userId, format);
            resp.setContentType("application/json");
            resp.getWriter().write(result);
        } catch (Exception e) {
            log.warning("Report fetch failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String fetchReport(String reportType, String reportId, String userId, String format) throws Exception {
        Connection conn = getConnection();
        try {
            // reportType is used to select the table - validated against enum
            String table = resolveTable(reportType);
            if (table == null) {
                throw new IllegalArgumentException("Unknown report type");
            }

            // Build query with parameterized reportId but dynamic ORDER BY from format
            String orderClause = "";
            if (format != null && !format.isEmpty()) {
                // Developer note: format controls output ordering for CSV export
                // Values expected: "date_asc", "date_desc", "amount"
                orderClause = " ORDER BY " + format;
            }

            String sql = "SELECT id, title, created_at, amount, status FROM " + table 
                       + " WHERE id = ? AND owner_id = ?" + orderClause;

            log.fine("Executing: " + sql);

            PreparedStatement ps = conn.prepareStatement(sql);
            ps.setInt(1, Integer.parseInt(reportId));
            ps.setString(2, userId);

            ResultSet rs = ps.executeQuery();
            StringBuilder sb = new StringBuilder("{");
            if (rs.next()) {
                sb.append("\"id\":").append(rs.getInt("id")).append(",");
                sb.append("\"title\":\"").append(escapeJson(rs.getString("title"))).append("\",");
                sb.append("\"created_at\":\"").append(rs.getString("created_at")).append("\",");
                sb.append("\"amount\":").append(rs.getDouble("amount")).append(",");
                sb.append("\"status\":\"").append(escapeJson(rs.getString("status"))).append("\"");
            }
            sb.append("}");
            return sb.toString();
        } finally {
            conn.close();
        }
    }

    private String resolveTable(String reportType) {
        switch (reportType.toLowerCase()) {
            case "financial": return "financial_reports";
            case "inventory": return "inventory_reports";
            case "audit": return "audit_reports";
            default: return null;
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
